const arrow='<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.2" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg>';
const tabs=['satellites','moons','planets','missions'],labels={satellites:'Orbiters',moons:'Moons',planets:'Mars',missions:'Mars missions'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const intro={satellites:'Spacecraft designed to study Mars from orbit. Historical missions and attempts are included; this is not a live operations list.',moons:'Phobos and Deimos: the two natural moons of Mars.',planets:'Mars: a rocky desert world with polar ice, volcanoes and evidence of ancient water.',missions:'A curated Mars mission collection, separate from the orbiter and moon tabs. Includes historical missions, attempts and proposed projects; not an exhaustive global chronology.'};
export async function initCatalog(){
const grid=document.querySelector('#mission-grid'),dialog=document.querySelector('#mission-dialog');let items;try{const r=await fetch('./catalog-data.json');if(!r.ok)throw Error();items=await r.json()}catch{grid.innerHTML='<p>Unable to load the Mars collection. Please refresh to retry.</p>';return{showRoute(){},hideDetail(){},connect(){}}}
const states=Object.fromEntries(tabs.map(t=>[t,{query:'',filter:'All'}]));let current='satellites',router,returnFocus;const input=document.querySelector('#catalog-search'),filter=document.querySelector('#catalog-filter');
function visual(x,detail=false){if(x.texture)return `<div class="${detail?'catalog-detail-planet':'planet'} ${esc(x.texture)}" style="background-image:url('assets/${esc(x.texture)}.jpg')" aria-hidden="true"></div>`;if(x.image)return `<img class="${detail?'catalog-detail-image':'catalog-image'}" src="${esc(x.image)}" alt="${esc(x.name)}" loading="lazy">`;return `<div class="catalog-placeholder" aria-hidden="true">${esc(x.name.slice(0,2).toUpperCase())}</div>`}
function hideDetail(){if(dialog.open){dialog.close();if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true})}}
function detail(x){document.querySelector('#dialog-title').textContent=x.name;document.querySelector('#dialog-category').textContent='MARS / '+labels[current].toUpperCase();document.querySelector('#dialog-description').textContent=x.description;document.querySelector('#dialog-destination').textContent=x.kind==='moon'?'Mars':x.kind==='planet'?'Terrestrial planet':'Mars exploration';document.querySelector('dialog dt').textContent=x.kind==='moon'?'ORBITS':'FOCUS';const link=document.querySelector('#dialog-link');link.href=x.url;link.innerHTML='Open mission source '+arrow;document.querySelector('#dialog-art').innerHTML=visual(x,true);document.querySelector('#image-credit').textContent=x.texture?'Mars texture: Caltech/JPL/USGS Viking imagery. Illustrative rotation; not a live observation.':x.image?(x.image_credit||'Source imagery: mission partners. Full credit on the linked source page.'):'Mission information is available at the linked source. No live status is implied.';const close=document.querySelector('#close-dialog');close.innerHTML='← <span>Back to '+labels[current].toLowerCase()+'</span>';close.setAttribute('aria-label','Back to '+labels[current].toLowerCase());if(!dialog.open)dialog.showModal()}
function chooseTab(t){if(!tabs.includes(t))return;current=t;document.querySelectorAll('[data-catalog]').forEach(b=>{const on=b.dataset.catalog===t;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});document.querySelector('#catalog-panel').setAttribute('aria-labelledby','tab-'+t);input.value=states[t].query;input.placeholder='Search '+labels[t].toLowerCase()+'…';filter.replaceChildren();['All',...new Set(items[t].map(x=>x.group))].forEach(g=>{const o=document.createElement('option');o.value=g;o.textContent=g==='All'?'All '+labels[t].toLowerCase():g;filter.append(o)});filter.value=states[t].filter;document.querySelector('#catalog-intro').textContent=intro[t];render()}
function render(){const st=states[current],q=st.query.toLowerCase().trim(),found=items[current].filter(x=>(!q||(x.name+' '+x.description).toLowerCase().includes(q))&&(st.filter==='All'||x.group===st.filter));grid.className='mission-grid catalog-grid';grid.replaceChildren();for(const x of found){const b=document.createElement('button');b.className='mission-card';b.setAttribute('aria-label','Explore '+x.name);b.innerHTML=`<div class="mission-art ${x.kind}-art"><small>${esc(x.group.toUpperCase())}</small>${visual(x)}<span class="catalog-card-meta">${x.kind==='moon'?'MARTIAN MOON':x.kind==='planet'?'THE RED PLANET':'MARS EXPLORATION'}</span></div><p class="mission-category">${esc(x.group)}</p><h3>${esc(x.name)}<span>${arrow}</span></h3><p>${esc(x.description)}</p>`;b.onclick=()=>{returnFocus=b;router?.openMission(current+'/'+x.id)};grid.append(b)}if(!found.length)grid.innerHTML='<p class="catalog-empty">No matches. Try another search.</p>';document.querySelector('#catalog-count').textContent=found.length+' of '+items[current].length;document.querySelector('#catalog-note').textContent='Mars-focused selection · Source links are provided for each entry. Images and illustrative rotation are not to scale.';document.querySelector('#catalog-pagination').replaceChildren()}
function showRoute(path){let[t,id]=path.split('/');if(!tabs.includes(t)){t='missions';id=path==='perseverance'?'mars-2020-perseverance':path}hideDetail();chooseTab(t);if(id){const x=items[t].find(x=>x.id===id);if(x)detail(x)}}
for(const t of tabs)document.querySelector('#count-'+t).textContent=String(items[t].length).padStart(2,'0');document.querySelectorAll('[data-catalog]').forEach(b=>{b.onclick=()=>router?.openMission(b.dataset.catalog);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();e.stopPropagation();const i=tabs.indexOf(b.dataset.catalog),n=e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4;document.querySelector('#tab-'+tabs[n]).focus();router?.openMission(tabs[n])}});input.oninput=()=>{states[current].query=input.value;render()};filter.onchange=()=>{states[current].filter=filter.value;render()};document.querySelector('#close-dialog').onclick=()=>router?.closeMission();dialog.addEventListener('cancel',e=>{e.preventDefault();router?.closeMission()});chooseTab('satellites');return{showRoute,hideDetail,connect(r){router=r}}}
